sed -i '/^}$/i \    fun saveLog(dateStr: String, flow: String, symptoms: List<String>, moods: List<String>, notes: String, emoji: String = "", takenMeds: String = "") {\n        viewModelScope.launch {\n            val existing = repository.getLogByDate(dateStr)\n            val log = DailyLog(\n                dateStr = dateStr,\n                periodFlow = flow,\n                symptoms = symptoms.joinToString(","),\n                moods = moods.joinToString(","),\n                notes = notes,\n                emoji = emoji,\n                takenMeds = takenMeds,\n                waterIntake = existing?.waterIntake ?: 0\n            )\n            repository.insertLog(log)\n            \n            // Sync this single log immediately to Firestore\n            val name = userName.value\n            if (name.isNotBlank()) {\n                firestoreManager.uploadLog(name, log)\n            }\n        }\n    }\n' app/src/main/java/com/example/ui/viewmodel/MahitaViewModel.kt
